/**
 * CheckboxGroup FSM - Finite State Machine for group selection behavior
 *
 * Manages tri-state selection logic for checkbox groups:
 * - none: No items selected
 * - some: Some items selected (indeterminate)
 * - all: All enabled items selected
 *
 * This FSM is pure and testable - no React dependencies.
 * The component uses useReducer with this reducer.
 *
 * @module CheckboxGroup/FSM
 */

// =============================================================================
// State Types
// =============================================================================

/**
 * Group selection state - determines the visual state of the "select all" checkbox
 */
export type GroupSelectionState = 'none' | 'some' | 'all';

/**
 * FSM state for CheckboxGroup
 */
export interface CheckboxGroupFSMState {
  /** Currently selected values */
  selectedValues: string[];
  /** Derived selection state based on selected count vs total enabled */
  selectionState: GroupSelectionState;
}

// =============================================================================
// Event Types
// =============================================================================

/**
 * Reset state from controlled props - used when value prop changes
 */
export interface ResetFromPropsEvent {
  type: 'RESET_FROM_PROPS';
  /** New selected values from props */
  values: string[];
  /** Total count of enabled (non-disabled) options */
  totalEnabled: number;
}

/**
 * Toggle a single item's selection state
 */
export interface ToggleItemEvent {
  type: 'TOGGLE_ITEM';
  /** Value of the item being toggled */
  value: string;
  /** Total count of enabled options */
  totalEnabled: number;
}

/**
 * Toggle all items via the "select all" checkbox
 */
export interface ToggleAllEvent {
  type: 'TOGGLE_ALL';
  /** Total count of enabled options */
  totalEnabled: number;
  /** Array of all enabled option values */
  enabledValues: string[];
}

/**
 * Union of all FSM events
 */
export type CheckboxGroupFSMEvent = ResetFromPropsEvent | ToggleItemEvent | ToggleAllEvent;

// =============================================================================
// State Derivation
// =============================================================================

/**
 * Derives the selection state from selected values and total enabled count
 *
 * @param selectedValues - Currently selected values
 * @param totalEnabled - Total number of enabled options
 * @returns The derived selection state
 */
export function deriveSelectionState(
  selectedValues: string[],
  totalEnabled: number
): GroupSelectionState {
  const count = selectedValues.length;

  // No items selected
  if (count === 0) {
    return 'none';
  }

  // All enabled items selected
  if (count >= totalEnabled && totalEnabled > 0) {
    return 'all';
  }

  // Some items selected
  return 'some';
}

// =============================================================================
// Initial State Factory
// =============================================================================

/**
 * Creates the initial FSM state
 *
 * @param values - Initial selected values
 * @param totalEnabled - Total number of enabled options
 * @returns Initial FSM state
 */
export function createInitialCheckboxGroupFSMState(
  values: string[],
  totalEnabled: number
): CheckboxGroupFSMState {
  // Deduplicate values
  const selectedValues = [...new Set(values)];

  return {
    selectedValues,
    selectionState: deriveSelectionState(selectedValues, totalEnabled),
  };
}

// =============================================================================
// FSM Reducer
// =============================================================================

/**
 * Pure reducer for CheckboxGroup FSM
 *
 * Handles all state transitions:
 * - RESET_FROM_PROPS: Sync state with controlled props
 * - TOGGLE_ITEM: Toggle a single item's selection
 * - TOGGLE_ALL: Select all or clear all based on current state
 *
 * @param state - Current FSM state
 * @param event - Event to process
 * @returns New FSM state
 */
export function checkboxGroupFSMReducer(
  state: CheckboxGroupFSMState,
  event: CheckboxGroupFSMEvent
): CheckboxGroupFSMState {
  switch (event.type) {
    case 'RESET_FROM_PROPS': {
      // Sync state with new controlled values
      const selectedValues = [...new Set(event.values)];
      return {
        selectedValues,
        selectionState: deriveSelectionState(selectedValues, event.totalEnabled),
      };
    }

    case 'TOGGLE_ITEM': {
      const { value, totalEnabled } = event;
      const selected = new Set(state.selectedValues);

      // Toggle the item
      if (selected.has(value)) {
        selected.delete(value);
      } else {
        selected.add(value);
      }

      const selectedValues = Array.from(selected);
      return {
        selectedValues,
        selectionState: deriveSelectionState(selectedValues, totalEnabled),
      };
    }

    case 'TOGGLE_ALL': {
      const { enabledValues, totalEnabled } = event;

      let selectedValues: string[];

      if (state.selectionState === 'all') {
        // All selected → clear all
        selectedValues = [];
      } else {
        // None or some selected → select all enabled
        selectedValues = [...enabledValues];
      }

      return {
        selectedValues,
        selectionState: deriveSelectionState(selectedValues, totalEnabled),
      };
    }

    default: {
      // TypeScript exhaustiveness check
      const _exhaustive: never = event;
      return _exhaustive;
    }
  }
}

// =============================================================================
// Event Creators
// =============================================================================

/**
 * Creates a RESET_FROM_PROPS event
 */
export function resetFromPropsEvent(values: string[], totalEnabled: number): ResetFromPropsEvent {
  return { type: 'RESET_FROM_PROPS', values, totalEnabled };
}

/**
 * Creates a TOGGLE_ITEM event
 */
export function toggleItemEvent(value: string, totalEnabled: number): ToggleItemEvent {
  return { type: 'TOGGLE_ITEM', value, totalEnabled };
}

/**
 * Creates a TOGGLE_ALL event
 */
export function toggleAllEvent(enabledValues: string[], totalEnabled: number): ToggleAllEvent {
  return { type: 'TOGGLE_ALL', enabledValues, totalEnabled };
}

// =============================================================================
// Predicates
// =============================================================================

/**
 * Check if selection state is 'none'
 */
export function isNoneSelected(state: CheckboxGroupFSMState): boolean {
  return state.selectionState === 'none';
}

/**
 * Check if selection state is 'some' (indeterminate)
 */
export function isSomeSelected(state: CheckboxGroupFSMState): boolean {
  return state.selectionState === 'some';
}

/**
 * Check if selection state is 'all'
 */
export function isAllSelected(state: CheckboxGroupFSMState): boolean {
  return state.selectionState === 'all';
}

/**
 * Check if a specific value is selected
 */
export function isValueSelected(state: CheckboxGroupFSMState, value: string): boolean {
  return state.selectedValues.includes(value);
}

/**
 * CheckboxGroup Component
 *
 * A high-level component for managing groups of checkboxes with tri-state
 * selection logic. Uses the Checkbox primitive internally without modifying it.
 *
 * Features:
 * - Tri-state selection: none / some / all
 * - Optional "select all" checkbox with indeterminate state
 * - Controlled and uncontrolled modes
 * - Proper group-level accessibility (fieldset/legend)
 * - FSM-based state management for predictable behavior
 *
 * Security Features:
 * - Uses Checkbox component which has safe attribute whitelist
 * - No dangerouslySetInnerHTML
 * - Props are typed and validated
 *
 * @see https://getbootstrap.com/docs/5.3/forms/checks-radios/
 * @module CheckboxGroup
 */

import { forwardRef, memo, useCallback, useEffect, useId, useMemo, useReducer } from 'react';

import { useControllableState } from '../../hooks';
import { cn } from '../../utils';
import { Checkbox } from '../Checkbox/Checkbox';

import {
  checkboxGroupFSMReducer,
  createInitialCheckboxGroupFSMState,
  resetFromPropsEvent,
  toggleAllEvent,
  toggleItemEvent,
} from './CheckboxGroup.fsm';

import type { CheckboxGroupProps } from './CheckboxGroup.types';

// Development warning for accessibility
const warnedGroups = new Set<string>();

function warnMissingGroupLabel(groupId: string): void {
  if (
    typeof process !== 'undefined' &&
    // biome-ignore lint/complexity/useLiteralKeys: noPropertyAccessFromIndexSignature requires bracket access
    process.env?.['NODE_ENV'] !== 'production' &&
    !warnedGroups.has(groupId)
  ) {
    warnedGroups.add(groupId);
    console.warn(
      `[DSAi CheckboxGroup] Missing accessible label. ` +
        `Provide a "label" prop or "aria-label"/"aria-labelledby" for screen reader users. ` +
        `This warning will only appear in development mode.`
    );
  }
}

/**
 * CheckboxGroup Component
 *
 * Manages a group of Checkbox components with tri-state selection logic.
 *
 * @example
 * ```tsx
 * // Basic usage
 * <CheckboxGroup
 *   label="Notification preferences"
 *   options={[
 *     { value: 'email', label: 'Email' },
 *     { value: 'sms', label: 'SMS' },
 *     { value: 'push', label: 'Push notifications' },
 *   ]}
 *   onChange={(values) => console.log('Selected:', values)}
 * />
 *
 * // With select all
 * <CheckboxGroup
 *   label="Select items"
 *   showSelectAll
 *   options={options}
 *   value={selected}
 *   onChange={setSelected}
 * />
 * ```
 */
const CheckboxGroupComponent = forwardRef<HTMLFieldSetElement, CheckboxGroupProps>(
  (
    {
      label,
      helperText,
      options,
      value,
      defaultValue,
      onChange,
      name,
      required = false,
      showSelectAll = false,
      selectAllLabel = 'Select all',
      error = false,
      errorMessage,
      disabled = false,
      className = '',
      style,
      id: providedId,
      orientation = 'vertical',
      size,
      variant,
      'aria-label': ariaLabel,
      'aria-labelledby': ariaLabelledby,
      'aria-describedby': ariaDescribedby,
    },
    ref
  ) => {
    // Generate unique IDs
    const generatedId = useId();
    const id = providedId || generatedId;
    const labelId = `${id}-label`;
    const helperId = `${id}-helper`;
    const errorId = `${id}-error`;

    // Compute enabled options
    const enabledOptions = useMemo(
      () => options.filter((opt) => !opt.disabled && !disabled),
      [options, disabled]
    );
    const enabledValues = useMemo(() => enabledOptions.map((opt) => opt.value), [enabledOptions]);
    const totalEnabled = enabledValues.length;

    // Use centralized hook for controlled/uncontrolled state management
    const [selectedValues, setSelectedValues] = useControllableState<string[]>({
      value,
      defaultValue: defaultValue ?? [],
      onChange,
    });

    // Initialize FSM state with current selected values
    const [fsmState, dispatch] = useReducer(
      checkboxGroupFSMReducer,
      { values: selectedValues, totalEnabled },
      (init) => createInitialCheckboxGroupFSMState(init.values, init.totalEnabled)
    );

    // Sync FSM with current selected values (controlled or uncontrolled)
    useEffect(() => {
      dispatch(resetFromPropsEvent(selectedValues, totalEnabled));
    }, [selectedValues, totalEnabled]);

    // Dev warning for missing accessible label
    useEffect(() => {
      if (!label && !ariaLabel && !ariaLabelledby) {
        warnMissingGroupLabel(id);
      }
    }, [label, ariaLabel, ariaLabelledby, id]);

    // Handle individual item toggle
    const handleToggleItem = useCallback(
      (optionValue: string) => {
        // Compute next state
        const nextState = checkboxGroupFSMReducer(
          fsmState,
          toggleItemEvent(optionValue, totalEnabled)
        );
        // Update selected values via hook (handles both controlled and uncontrolled)
        setSelectedValues(nextState.selectedValues);
      },
      [fsmState, totalEnabled, setSelectedValues]
    );

    // Handle "select all" toggle
    const handleToggleAll = useCallback(() => {
      // Compute next state
      const nextState = checkboxGroupFSMReducer(
        fsmState,
        toggleAllEvent(enabledValues, totalEnabled)
      );
      // Update selected values via hook (handles both controlled and uncontrolled)
      setSelectedValues(nextState.selectedValues);
    }, [fsmState, enabledValues, totalEnabled, setSelectedValues]);

    // Derive selection state for rendering (selectedValues managed by useControllableState)
    const { selectionState } = fsmState;
    const renderSelectedValues = fsmState.selectedValues;
    const selectAllChecked = selectionState === 'all';
    const selectAllIndeterminate = selectionState === 'some';

    // Build class names
    const wrapperClasses = useMemo(
      () => cn('checkbox-group', error && 'has-error', className),
      [error, className]
    );

    const optionsClasses = useMemo(
      () => cn('checkbox-group-options', orientation === 'horizontal' && 'd-flex flex-wrap gap-3'),
      [orientation]
    );

    // Compute describedby
    const computedDescribedby = useMemo(() => {
      const parts: string[] = [];
      if (ariaDescribedby) {
        parts.push(ariaDescribedby);
      }
      if (helperText) {
        parts.push(helperId);
      }
      if (error && errorMessage) {
        parts.push(errorId);
      }
      return parts.length > 0 ? parts.join(' ') : undefined;
    }, [ariaDescribedby, helperText, helperId, error, errorMessage, errorId]);

    // Content inside fieldset
    const content = (
      <>
        {/* Legend */}
        {label && (
          <legend id={labelId} className="checkbox-group-legend fw-semibold mb-2">
            {label}
            {required && <span className="text-danger ms-1">*</span>}
          </legend>
        )}

        {/* Helper text */}
        {helperText && (
          <div id={helperId} className="form-text mb-2">
            {helperText}
          </div>
        )}

        {/* Select all checkbox */}
        {showSelectAll && (
          <div className="checkbox-group-select-all mb-2">
            <Checkbox
              label={selectAllLabel}
              checked={selectAllChecked}
              indeterminate={selectAllIndeterminate}
              onChange={handleToggleAll}
              disabled={disabled || totalEnabled === 0}
              size={size}
              variant={variant}
              aria-controls={options.map((opt) => `${id}-option-${opt.value}`).join(' ')}
            />
          </div>
        )}

        {/* Options */}
        <div className={optionsClasses} data-visual-state={selectionState}>
          {options.map((option) => {
            const optionId = `${id}-option-${option.value}`;
            const isSelected = renderSelectedValues.includes(option.value);
            const isDisabled = disabled || option.disabled;

            return (
              <Checkbox
                key={option.value}
                id={optionId}
                name={name}
                value={option.value}
                label={option.label}
                checked={isSelected}
                onChange={() => handleToggleItem(option.value)}
                disabled={isDisabled}
                required={required}
                helperText={option.helperText}
                inline={orientation === 'horizontal'}
                size={size}
                variant={variant}
              />
            );
          })}
        </div>

        {/* Error message */}
        {error && errorMessage && (
          <div id={errorId} className="invalid-feedback d-block">
            {errorMessage}
          </div>
        )}
      </>
    );

    return (
      <fieldset
        ref={ref}
        id={id}
        aria-labelledby={ariaLabelledby}
        aria-label={!label && !ariaLabelledby ? ariaLabel : undefined}
        aria-describedby={computedDescribedby}
        aria-invalid={error || undefined}
        className={wrapperClasses}
        style={style}
        disabled={disabled}
      >
        {content}
      </fieldset>
    );
  }
);

CheckboxGroupComponent.displayName = 'CheckboxGroup';

// Memoize component to prevent unnecessary re-renders
export const CheckboxGroup = memo(CheckboxGroupComponent);

// Preserve displayName through memo wrapper
CheckboxGroup.displayName = 'CheckboxGroup';

// Re-export types
export type { CheckboxGroupOption, CheckboxGroupProps } from './CheckboxGroup.types';

/**
 * CheckboxGroup Types
 *
 * Type definitions for the CheckboxGroup component.
 * CheckboxGroup is a high-level component that manages a group of Checkbox components
 * with tri-state (none/some/all) selection logic.
 *
 * @module CheckboxGroup/Types
 */

import type { ComponentSize, SemanticColorVariant } from '../../types';
import type { CSSProperties, ReactNode } from 'react';

// =============================================================================
// Option Types
// =============================================================================

/**
 * Configuration for a single option in the checkbox group
 */
export interface CheckboxGroupOption {
  /**
   * Unique value for the option
   * Used to track selection state
   */
  value: string;

  /**
   * Label displayed next to the checkbox
   */
  label: ReactNode;

  /**
   * Whether this option is disabled
   * Disabled options cannot be selected and are excluded from "select all"
   * @default false
   */
  disabled?: boolean;

  /**
   * Helper text for this specific option
   */
  helperText?: ReactNode;
}

// =============================================================================
// Component Props
// =============================================================================

/**
 * Props for the CheckboxGroup component
 */
export interface CheckboxGroupProps {
  /**
   * Label for the entire group
   * Rendered as a <legend> inside a <fieldset>
   * Required unless aria-label or aria-labelledby is provided
   */
  label?: ReactNode;

  /**
   * Helper text for the group
   * Displayed below the legend
   */
  helperText?: ReactNode;

  /**
   * Array of options to render as checkboxes
   */
  options: CheckboxGroupOption[];

  /**
   * Controlled selected values
   * Array of option values that are currently selected
   */
  value?: string[];

  /**
   * Default selected values (uncontrolled mode)
   * Array of option values to select initially
   */
  defaultValue?: string[];

  /**
   * Callback fired when selection changes
   * Receives the new array of selected values
   */
  onChange?: (values: string[]) => void;

  /**
   * Shared name attribute for all checkboxes in the group
   * Useful for form submission
   */
  name?: string;

  /**
   * Whether at least one option must be selected
   * @default false
   */
  required?: boolean;

  /**
   * Whether to show a "select all" checkbox at the top of the group
   * This checkbox uses indeterminate state when some options are selected
   * @default false
   */
  showSelectAll?: boolean;

  /**
   * Label for the "select all" checkbox
   * Only used when showSelectAll is true
   * @default "Select all"
   */
  selectAllLabel?: ReactNode;

  /**
   * Whether the group is in an error state
   * @default false
   */
  error?: boolean;

  /**
   * Error message to display when error is true
   */
  errorMessage?: ReactNode;

  /**
   * Whether all options are disabled
   * @default false
   */
  disabled?: boolean;

  /**
   * Additional CSS class name for the fieldset
   */
  className?: string;

  /**
   * Inline styles for the fieldset
   */
  style?: CSSProperties;

  /**
   * ID attribute for the fieldset
   */
  id?: string;

  /**
   * Orientation of the checkboxes
   * @default "vertical"
   */
  orientation?: 'horizontal' | 'vertical';

  /** Size variant passed to all child Checkbox components */
  size?: ComponentSize;

  /** Color variant passed to all child Checkbox components */
  variant?: SemanticColorVariant;

  /**
   * Accessible label for the group when label prop is not visible text
   * Use when label is an icon or other non-text content
   */
  'aria-label'?: string;

  /**
   * ID of an element that labels this group
   * Alternative to label prop for custom layouts
   */
  'aria-labelledby'?: string;

  /**
   * ID of an element that describes this group
   * Alternative to helperText for custom layouts
   */
  'aria-describedby'?: string;
}

// =============================================================================
// Re-export FSM Types for convenience
// =============================================================================

export type { CheckboxGroupFSMState, GroupSelectionState } from './CheckboxGroup.fsm';

/**
 * CheckboxGroup Component
 *
 * High-level component for managing checkbox groups with tri-state selection.
 *
 * @module CheckboxGroup
 */

export { CheckboxGroup } from './CheckboxGroup';
export type { CheckboxGroupFSMState, GroupSelectionState } from './CheckboxGroup.fsm';
// Export FSM utilities for advanced usage
export {
  checkboxGroupFSMReducer,
  createInitialCheckboxGroupFSMState,
  deriveSelectionState,
  isAllSelected,
  isNoneSelected,
  isSomeSelected,
  isValueSelected,
  resetFromPropsEvent,
  toggleAllEvent,
  toggleItemEvent,
} from './CheckboxGroup.fsm';
export type { CheckboxGroupOption, CheckboxGroupProps } from './CheckboxGroup.types';
